/* ==UserStyle==
@name ديسكورد القديم - نسخة كلاسيكية
@namespace discord-old-style-ar
@version 1.0.1
@description يعيد شكل وألوان ديسكورد القديمة بتصميم كلاسيكي داكن واجهة مريحة للعين.
@license مجاني للاستخدام الشخصي
@preprocessor none
==/UserStyle== */

/* ملاحظات الإصدار:
الإصدار 1.0.1:
- تحسين تباين الألوان
- تحسين مظهر الأزرار والقوائم

الإصدار 1.0.0:
- الإصدار الأول للثيم
*/

:root {
  --background-primary: #2c2f33 !important;
  --background-secondary: #23272a !important;
  --background-tertiary: #1e2124 !important;
  --header-primary: #ffffff !important;
  --header-secondary: #b9bbbe !important;
  --interactive-normal: #b9bbbe !important;
  --interactive-hover: #ffffff !important;
  --interactive-active: #7289da !important;
}

/* قائمة السيرفرات */
div[class*="guilds"] {
  background-color: var(--background-tertiary) !important;
}

/* قائمة القنوات */
div[class*="sidebar"] {
  background-color: var(--background-secondary) !important;
}

/* منطقة المحادثة */
div[class*="chatContent"] {
  background-color: var(--background-primary) !important;
}

/* نصوص الرسائل */
div[class*="messageContent"] {
  color: var(--header-primary) !important;
}

/* الأزرار */
button {
  background-color: #7289da !important;
  color: #ffffff !important;
  border-radius: 4px !important;
}

/* إخفاء العناصر الجديدة غير المهمة */
[aria-label="Shop"],
[aria-label="Clips"] {
  display: none !important;
}
